const LEDGER=PWL.judgeBlock({cr1:F.cr1,gr1:F.gr1,cr2:F.cr2,gr2:F.gr2,cr3:F.cr3,dr3:F.dr3})+(t=>t?String.fromCharCode(10,10)+t:'')((()=>{try{return PWL.cList({dr3:F.dr3});}catch(e){return '';}})()); // BB-7397 rev 9 DoD 26 (1)
const NL=String.fromCharCode(10);
const KJVC=(()=>{let x=null;try{x=$('Quote Report').first().json;}catch(e){x=null;}
 if(!x||x.unavailable||!Array.isArray(x.items))return 'CITATION CHECK AGAINST THE KJV: not available this run; grade citations as usual.';
 const bad=x.items.filter(i=>i.status&&i.status!=='MATCHES'&&i.status!=='NOT CHECKED');
 const head='CITATION CHECK AGAINST THE KJV -- computed by the system from the KJV text, not by a model: '+x.checked+' quotations given with a reference; '+x.matches+' match the verse cited; '+bad.length+' do not; '+x.not_checked+' too short to check.';
 // Item 7 (4), WALL-1844: an unchecked load-bearing quotation is listed by reference, so the judge reads that verse itself.
 const ncl=x.items.filter(i=>i.status==='NOT CHECKED'&&i.load_bearing);
 const ncs=ncl.length?NL+'NOT CHECKED BY THE SYSTEM, load-bearing (read the verse yourself before you credit the link): '+ncl.map(i=>i.side+' '+i.round+(i.link?' LINK '+i.link:'')+': '+i.ref).join('; ')+'.':'';
 if(!bad.length)return head+ncs;
 return head+ncs+NL+bad.map(i=>i.side+' '+i.round+': cited '+i.ref+': "'+String(i.quote).slice(0,160)+'" -- '+i.status).join(NL)+NL+'RULE: a quotation whose words ARE AT another verse is real KJV text cited to the wrong place: name it as a citation error in your justification; it still counts as [L1] footing for the words quoted. A quotation whose wording DIFFERS FROM its cited verse, or is NOT FOUND in the book named, or whose cited verse does not exist, is NOT [L1] footing for any link that rests on it. A citation error by one side never counts for or against the other side.';})();

// ONE RULEBOOK (operator-approved 2026-10-04): the panel judges by the same layer rules, verdict definitions and standing
// definitions as the single judge (Build Independent Verdict, ODV1-A1). Rule text below is carried verbatim from that node;
// only the output form differs (strict JSON; the worked lines go in "reasoning").
let SYS=['You are ONE of three INDEPENDENT judges of a completed debate. You have not seen the other judges and you will not. Judge only what is in the transcript below. You are bound by the same layer rules as all debate participants, and by the same rulebook as every other judge of this debate.','','Grade each side by its ROLE; neither reading is presumed.','','Name people and things only in the KJV\'s own words or in plain English; no titles, honorifics or capitalised epithets the text does not use (it says \'the child\', not \'the Boy\'); every Greek or Hebrew word you use is followed by its plain English meaning.','','RETURN STRICT JSON AND NOTHING ELSE. No prose before or after it. No code fences.','{','  "verdict_tag": "HELD" | "PARTIAL" | "BROKEN",','  "defense_standing": "SELF-SUPPORTED" | "PROP-DEPENDENT" | "COLLAPSED",','  "challenge_standing": "SELF-SUPPORTED" | "PROP-DEPENDENT" | "COLLAPSED",','  "conceded_links": integer >= 0,','  "challenger_conceded_links": integer >= 0,','  "counted_premises_defender": array of integers -- the PRESSED-WITNESS LEDGER premise numbers (AGAINST THE DEFENDER) you counted in conceded_links; [] when none','  "counted_premises_challenger": array of integers -- the PRESSED-WITNESS LEDGER premise numbers (AGAINST THE CHALLENGER) you counted in challenger_conceded_links; [] when none','  "reasoning": string -- the worked grading: the RESULT line, the CLAUSE line, KEYSTONE, both standings with their justification, both conceded-link itemizations, COLLISION POINTS, the citation check, OUT-OF-ROUND CONCESSIONS, DEFENDER CHAIN MARK and CHALLENGER CHAIN MARK, in the forms the rulebook below gives, one per line (newlines escaped as \\n inside the JSON string)','}','','THESE TOKENS ARE EXACT AND THE SETS ARE CLOSED. A value outside them is a FAILED judgment, not a nuance, and it will be counted as unreadable. Do NOT return "UNKNOWN" and do NOT invent a fourth tag: an UNKNOWN tag is scored as unclean AND is invisible to the unrecognised-tag report, so it is the one answer that hides itself.','','verdict_tag MUST be the verdict word the VERDICT DEFINITIONS below give (first match wins). defense_standing, challenge_standing, conceded_links and challenger_conceded_links MUST equal the values your reasoning reaches under the rulebook; each counted_premises array MUST list exactly the premises its count counts.','','THE RULEBOOK','','JUDGE LAYER RULES:'+NL+'[L1]=KJV text. [L2]=Hebrew/Greek. [L3]=Cross-reference. [L4]=Inference -- flag explicitly.'+NL+'Evaluate ONLY what was argued in this transcript.',
"THE FRAMEWORK IS NOT A COMBATANT. The framework is the Rules of Engagement and Rules of Interaction -- Isaiah 28:10 method, the L1-L4 layer rules, the burden rule -- and it binds BOTH combatants equally. The debate is about the TOPIC. The DEFENDER holds a chain of interlocking citations on the topic; the CHALLENGER presses an opposing view and settles it only by breaking that chain. A claim by either side that restates resolved ground with its stating verses cited is not an overpress."+NL+"This debate was CHAIN-SCOPED (Isaiah 28:10 declared): judge whether the DEFENDER'S CHAIN on the topic survived as a chain -- isolated-link objections that never engage the chain do not break it. The rule cuts both ways: an objection that is itself a floating [L4] (no exhibited layer footing) cannot break a link that exhibits its footing. Name every floating [L4] on either side before weighing it; an [L4] floats only when the block that states it exhibits fewer than two prior layers ([L1]-[L3]) for it; that one test applies to the defender and the challenger alike. That no quoted row states an [L4] is never a reason to call it floating: an [L4] is an inference by definition, and that demand is the retired stating-verse test, at a collision as everywhere else. The same holds against the challenger: a challenger premise or answer whose support is that no verse states the defender\'s link, or an exclusion, in its own words is that retired test and is not SUPPORTED on that ground. A reading cited from the Septuagint (LXX) is a citation error for either side: name it at the citation check and give it no weight as footing. A judge that names an [L4] floating names, in the same sentence, the layers its block exhibits and the layer it lacks. An [L4] whose block exhibits two or more prior layers is footed for either side and is weighed at its collision on the rows it rests on; the witnesses held to contradict it are quoted, and they contradict it read together, line upon line; an inference admitted through the prior layers (Isaiah 28:10) is EVIDENCE, an inference that floats free of the text is not.",'',preCheckBlock(F),'',
'COUNTING RULE -- BINDING, read before grading: grade and COUNT only from the two LINK ROUND blocks above, [CR3] (defender) and [DR3] (challenger); an ANSWER to a pressed witness is read from any later round of the side that holds the link, its round 2 or its link round. The POST-DEBATE ANALYSIS block is CONTEXT ONLY and is NOT evidence of concession -- never take a count from it, and ignore the word "unanswered" wherever it appears there. In this format the challenger link round [DR3] is structurally LAST: no defender round follows it, so the defender being silent after [DR3] is procedural and is NEVER a challenger concession. A premise counts as CONCEDED only if the link round block itself states it as conceded, or exhibits no layer footing for it in that block. UNANSWERED WITNESS: a verse the other side quoted against a link or a listed premise in an earlier round (against the defender: [DR1] and [DR2]; against the challenger: [CR1], [CR2] and [CR3]) is ANSWERED when any later round of the side that holds the link (for the defender: [CR2] or [CR3]; for the challenger: [DR2] or [DR3]) quotes it or names it by reference and shows from the text why it does not overturn the link. Re-citing the link\'s own footing while passing over the witness pressed against it is not an answer. A premise whose pressed witness goes unanswered is UNEXHIBITED: it counts toward CONCEDED LINKS and the standings. In a debate a non-response is never neutral. A verse on a side\'s \'cited in\' line counts as an unanswered witness only when the judge quotes the sentence of the earlier round that pressed it against that link or a listed premise and names that round; a verse cited there but not pressed against the link does not count. A judge who grades a link BROKEN because the witnesses exclude, deny or establish something must quote the words that state it; where the quoted words, read in their own context and with the other verses the judge quotes, do not state it, the ground is the judge\'s own [L4] inference, and it counts only when the judge exhibits two lower layers ([L1]-[L3]) for it, as submitted evidence must; otherwise it is no ground for BROKEN, and the link is graded under the remaining rules. UNCHALLENGED: everything a side presents is open to challenge. A link or a witness the other side never challenged in any of its rounds stands as HELD for the side that presented it, and the silent side may not contest it in the verdict. A claim a side restates in its own link round is graded at the layer and with the footing it exhibits there; an earlier [L4] label of the same claim does not survive the restatement.'+NL+NL+'VERDICT DEFINITIONS -- apply these mechanically, first match wins; not your own scale.'+NL+"TERMS. DEFENDER LINKS: the links of the DEFENDER'S OWN DECLARED CHAIN as written in [CR1] under its anchored DECLARED CHAIN heading, numbered D1..Dn in that order; n = their number. The LAST declared link, Dn, is the conclusion link. THE ROUND 1 CHAIN GOVERNS. n, the numbering D1..Dn and the keystone Dn come from the DECLARED CHAIN in [CR1] only. A chain the defender declares again in a later round, re-seated, revised or extended, never changes n, the numbering or the keystone: a link added later is not a declared link, and a [CR1] link left out later is still declared. A challenger premise written LINK i: is graded against Di. A challenger premise written LINK none: is JUDGED but is OUTSIDE n and never changes it. The challenger's listed premise count is NOT n and is never substituted for it. CHALLENGER LINKS: the premises listed for the challenger in [DR3], numbered C1..Cm in [DR3] order. WITHDRAWN: a defender link that [CR3] itself states as conceded or withdrawn, wholly or on a stated condition; tag it CONCEDED (stated) or CONCEDED (conditional: <condition>). w = their number. A withdrawn link that carries a witness pressed against it and left unanswered, by the UNANSWERED WITNESS test, in every round of its side before the round that withdraws it is still graded at its collision. Only the DECLARED links D1..Dn can enter w; a challenger premise written LINK none: is not a defender link and never enters w, however the defender treats it. No link is exempt from w as auxiliary, overreach, non-core or not load-bearing. A link is withdrawn or it is not. Pressure from the challenger's texts alone is not a withdrawal (w); a witness the side's later rounds leave unanswered is graded under UNANSWERED WITNESS and at the COLLISION POINTS. An UNEXHIBITED link counts toward CONCEDED LINKS and the standings, never toward w. BROKEN AT COLLISION: a defender link graded DEFENDER LINK BROKEN on the COLLISION POINTS lines; k = their number."+NL+'BROKEN-1: k >= 1 -- a listed defender link refuted from the text.'+NL+'BROKEN-2: 2w > n, OR the keystone link is WITHDRAWN.'+NL+'PARTIAL-1: w >= 1.'+NL+'PARTIAL-2: DEFENSE STANDING is COLLAPSED.'+NL+'HELD-1: none of the above.'+NL+'STANDINGS ARE GRADED BY THEIR OWN RULES ONLY. DEFENSE STANDING and CHALLENGE STANDING are each decided by their own definitions below and by nothing else. Any standing is legal with any CLAUSE: the clauses are tried in order and the first match wins, so a COLLAPSED standing under BROKEN-1, BROKEN-2 or PARTIAL-1 is correct and changes no clause. Never choose a standing, a count or a clause to agree with another line, a check or an expected result: when 2c > L the standing is COLLAPSED, whatever the clause.'+NL+'A SIDE WITH A COUNTED LINK IS NOT SELF-SUPPORTED. If CONCEDED LINKS is 1 or more, DEFENSE STANDING is PROP-DEPENDENT, or COLLAPSED when 2c > L; if CHALLENGER CONCEDED LINKS is 1 or more, CHALLENGE STANDING is PROP-DEPENDENT, or COLLAPSED when 2c > L. SELF-SUPPORTED requires a count of 0 for that side: every premise listed against it exhibited its footing or was VOID.'+NL+'Line 1: the verdict word first (HELD, PARTIAL or BROKEN), then 2-4 sentences with [L1][L2][L3][L4] tags.'+NL+'Line 2, exactly: RESULT: DEFENDER WINS | CHALLENGER WINS | UNDERDETERMINED -- one sentence a reader with no background understands. BROKEN gives CHALLENGER WINS. HELD gives DEFENDER WINS only if CHALLENGE STANDING is not SELF-SUPPORTED or at least one collision is graded CHALLENGER LINK BROKEN. Every other case gives UNDERDETERMINED.'+NL+'Line 3, exactly: CLAUSE: <BROKEN-1 | BROKEN-2 | PARTIAL-1 | PARTIAL-2 | HELD-1> -- n=<n> w=<w> k=<k>'+NL+NL+'Then SIX MORE mandatory lines, exactly in these forms:'+NL+'KEYSTONE: D<n> -- WITHDRAWN | BROKEN | STANDS -- name the LAST declared link, Dn, which is the conclusion link, and give its state. WITHDRAWN if it is withdrawn or conceded; BROKEN if it is graded DEFENDER LINK BROKEN at a collision; STANDS otherwise. The number after D MUST equal the n on the CLAUSE line, and the state MUST match that link\'s own D<n> entry.'+NL+'DEFENSE STANDING: SELF-SUPPORTED | PROP-DEPENDENT | COLLAPSED -- L=<L> c=<c> -- grade the DEFENDER only, using the STATED/INFERRED tags and the [CR3] LINK ROUND. SELF-SUPPORTED = every listed defender claim is carried by its layer stack -- each [L4] exhibits the [L1]/[L2]/[L3] footing it rests on (at least two prior layers exhibited; a shown chain counts equally). PROP-DEPENDENT = the defense survived only because listed [L4]s were allowed to stand WITHOUT exhibiting their prior-layer footing (floating inference; links conceded/unexhibited in the LINK ROUND). COLLAPSED = by count, mandatory, not discretionary: 2c > L, where L is the number of premises the CHALLENGER listed AGAINST the defender (the UNSUPPORTED-L4 PREMISES list that closes [DR2]) and c is the number of those the defender CONCEDED or left UNEXHIBITED in its LINK ROUND [CR3]. The premises the defender itself lists against the challenger at the end of [CR3] (CHALLENGER\'S UNSUPPORTED-L4 PREMISES) are the challenger\'s burden and NEVER enter the defender\'s L, c, CONCEDED LINKS or DEFENSE STANDING. FORFEIT: if the challenger listed no premises against the defender (an empty list, or PREMISE COUNT: 0), then L = 0, c = 0, CONCEDED LINKS is 0, DEFENSE STANDING cannot be COLLAPSED, and you add the line LINK ROUND FORFEITED: CHALLENGER -- no premises were listed against the defender. A LINK ROUND answer that neither exhibits the premise\'s layer footing nor concedes counts as CONCEDED. A tie (2c = L) is NOT COLLAPSED. COLLAPSED is reached by this count only; SELF-SUPPORTED against PROP-DEPENDENT is your judgment as defined above. A listed premise is countable only as charged IF the list carries the opponent\'s verbatim quote that states it; a premise listed without a verbatim quote, or charged in terms stronger than its quote, is VOID -- it counts for neither side, and a CONCEDED answer to a void premise is NOT a concession: name it VOID in your itemization and exclude it from every count and standing. A charge is stronger than its quote only when it asserts what the quote does not: a negation, a universal (all, none, only, never), or a claim the quote\'s own words do not make. Dropping, reordering or paraphrasing the quote\'s words is not stronger. A verse the list carries beside a premise under PRESSED WITH: is a witness pressed against that premise, not part of its charge: it never makes the charge stronger than its quote, and a premise is never VOID for carrying one. A limb the link round narrows counts in its narrowed form. A premise\'s quote is checked against every earlier round of the opponent; it is verbatim if found in any of them, and the judge names that round. A link honestly conceded as held inference still counts toward the count but note it as disciplined, not evasive. One sentence of justification.'+NL+'CONCEDED LINKS: <integer> -- the count of challenger-listed premises the defender CONCEDED or failed to exhibit its layer footing in [CR3]. Itemize the counted links and tag each with the clause that fired: CONCEDED (stated) when the block itself states the surrender; UNEXHIBITED (no footing offered) when the block asserted the link and offered no layer footing at all. A link whose block exhibits at least two prior layers of footing and shows the chain from them to the link is SUPPORTED and is not counted, even when no cited verse states the link\'s conclusion in words: an [L4] is an inference by definition, and demanding a verse that states it is the retired stating-verse test, which is never applied. When the count is lower than the number of links, name which links are counted and which are spared. Both tags count toward the single integer; keep the tags distinct in the itemization and do not report more than one number.'+NL+'CHALLENGE STANDING: SELF-SUPPORTED | PROP-DEPENDENT | COLLAPSED -- L=<L> c=<c> -- grade the CHALLENGER only, using the challenger\'s STATED/INFERRED tags and the [DR3] LINK ROUND. SELF-SUPPORTED = every listed objection is carried by its layer stack -- each [L4] exhibits the [L1]/[L2]/[L3] footing it rests on. PROP-DEPENDENT = the challenge survived only because listed [L4]s were allowed to stand without exhibiting their prior-layer footing (floating inference; links conceded/unexhibited in [DR3]). COLLAPSED = by count, mandatory, not discretionary: 2c > L, where L is the number of premises the DEFENDER listed AGAINST the challenger (the CHALLENGER\'S UNSUPPORTED-L4 PREMISES list that closes [CR3]) and c is the number of those the challenger CONCEDED or left UNEXHIBITED in its LINK ROUND [DR3]. The premises the challenger listed against the defender (the list that closes [DR2]) NEVER enter the challenger\'s L, c, CHALLENGER CONCEDED LINKS or CHALLENGE STANDING. FORFEIT: if the defender listed no premises against the challenger (an empty list), then L = 0, c = 0, CHALLENGER CONCEDED LINKS is 0, CHALLENGE STANDING cannot be COLLAPSED, and you add the line LINK ROUND FORFEITED: DEFENDER -- no premises were listed against the challenger. A LINK ROUND answer that neither exhibits the premise\'s layer footing nor concedes counts as CONCEDED. A tie (2c = L) is NOT COLLAPSED. COLLAPSED is reached by this count only; SELF-SUPPORTED against PROP-DEPENDENT is your judgment as defined above. A void premise (no verbatim quote, or charged beyond its quote) counts for neither side; a verse carried under PRESSED WITH: is a witness, never a charge, and never voids a premise. A link honestly conceded as held inference still counts toward the count but note it as disciplined, not evasive. One sentence of justification.'+NL+'CHALLENGER CONCEDED LINKS: <integer> -- the count of defender-listed premises the challenger CONCEDED or failed to exhibit its layer footing in [DR3]. Itemize the counted links and tag each with the clause that fired: CONCEDED (stated) when the block itself states the surrender; UNEXHIBITED (no footing offered) when the block asserted the link and offered no layer footing at all. A link whose block exhibits at least two prior layers of footing and shows the chain from them to the link is SUPPORTED and is not counted, even when no cited verse states the link\'s conclusion in words: an [L4] is an inference by definition, and demanding a verse that states it is the retired stating-verse test, which is never applied. When the count is lower than the number of links, name which links are counted and which are spared. Both tags count toward the single integer; keep the tags distinct in the itemization and do not report more than one number.'+NL+"COLLISION POINTS: the label on its own line, then one entry per line covering every defender link D1..Dn, none omitted. A link counted in w: D<i>: WITHDRAWN; or, for a link withdrawn after an unanswered witness, D<i> vs C<j> (<verse>): WITHDRAWN AFTER AN UNANSWERED WITNESS -- <grade> -- the grade counting as any collision grade. A link that a challenger link contradicts about the same text: D<i> vs C<j> (<verse>): DEFENDER LINK BROKEN | CHALLENGER LINK BROKEN | UNDERDETERMINED -- one clause of why; one such line per contradicting challenger link, and DEFENDER LINK BROKEN at most once per defender link. Any other link: D<i>: STANDS. CHAIN SCOPE (Isaiah 28:10): no single verse is required to state a link or its contrary. The witnesses a side exhibits, read together line upon line, are the text's own statement, and \"no single verse states it\" is never a ground for STANDS or UNDERDETERMINED. A link marked STANDS, or a collision graded UNDERDETERMINED, against a witness the other side exhibited names in the same line the round that answered that witness. A witness left unanswered is a BROKEN ground. That a single verse does not state a link or its contrary is never a ground for STANDS or UNDERDETERMINED, for either side. A witness contradicts a link only when its own words state the contrary; a verb that leaves the point unnarrated does not, for either side. This tests a pressed witness, not a chained premise, which is judged by its footing (DG-61). When the witnesses pressed against a link are the pressing side's own chain read together, the collision weighs chain against chain by footing, never verse by verse; that no one of them states the contrary in its own words is the stating-verse test DG-61 retires, at a judge's seat as at a debater's, for either side. Grade a link BROKEN when the other side exhibited [L1]/[L2]/[L3] witnesses that together contradict it and the broken side's later rounds left any of those witnesses UNANSWERED (COUNTING RULE). Grade UNDERDETERMINED only when the side's later rounds answered every such witness and the witnesses, read together, still leave the point open. k is the number of lines graded DEFENDER LINK BROKEN. A side with any link graded BROKEN here cannot be SELF-SUPPORTED.",'',"DEBATE RULE VIOLATION (Isaiah 28:10: \"here a little, [and] there a little\"). The rule on a BROKEN ground binds you as it binds the debaters. On every COLLISION POINTS line you grade DEFENDER LINK BROKEN or CHALLENGER LINK BROKEN, exhibit on that line itself at least two lower layers of DIFFERENT kinds, each tagged: [L1] with the KJV words quoted; [L2] with the Hebrew or Greek word in its own script, with its transliteration marks, or with its Strong's number; [L3] with the cross-reference named. Two quotations at one layer are one layer. A BROKEN line without them is a DEBATE RULE VIOLATION. The system checks every BROKEN line after you answer; a violating line is returned to you to cure, by exhibiting the two layers, or to answer in writing why it stands. An answer that does not exhibit them leaves the violation standing, and your judgment is then not counted. The same holds when your CONCEDED LINKS or CHALLENGER CONCEDED LINKS count is 0 while you grade a link of that side BROKEN for a witness left unanswered. Both sides alike.",'',
'CITATION CHECK, PER SEAT: held-record labels served to the DEFENDER this run: '+((IG.d_served.join(', '))||'(none)')+'. Served to the CHALLENGER this run: '+((IG.c_served.join(', '))||'(none)')+'. Named inside the text served to the DEFENDER (a served conclusion, guard or tension names them; their own text was not served): '+(((IG.d_named||[]).join(', '))||'(none)')+'. Named inside the text served to the CHALLENGER: '+(((IG.c_named||[]).join(', '))||'(none)')+'. Conclusions are #N, sights are S-N -- separate namespaces. A label in a side\'s named list is not a citation error: it carries only what the served sentence naming it says. Any conclusion or sight label a side cites that is in neither of that side\'s own lists was not served to it this run: treat it as unverified ground, do not let it carry weight, and name it in your justification as a citation error.'+' SERVED LABELS CITED -- computed by the system from the rounds, not by a model: DEFENDER '+SLC(IG.d_served,IG.d_named,[F.cr1,F.cr2,F.cr3])+'. CHALLENGER '+SLC(IG.c_served,IG.c_named,[F.gr1,F.gr2,F.dr3])+'.','',KJVC,'',LEDGER,'',
"OUT-OF-ROUND CONCESSIONS -- after the COLLISION POINTS lines, add a section titled exactly OUT-OF-ROUND CONCESSIONS, the title on its own line. List one line for each concession either side made OUTSIDE the two link rounds -- that is, ground granted in [CR1], [DR1], [CR2] or [DR2], not in [CR3] or [DR3]. Form, one per line: SIDE | ROUND | the verbatim sentence in which the ground was granted, where SIDE is DEFENDER or CHALLENGER. If there are none, write exactly: NONE. BINDING: these are recorded separately and DO NOT ENTER CONCEDED LINKS, CHALLENGER CONCEDED LINKS, DEFENSE STANDING, CHALLENGE STANDING, the CLAUSE line or the top-line verdict. The counting rule above is unchanged and still governs those lines: a premise counts as CONCEDED only from the link round block itself. Never sum an out-of-round concession with a link-round count."+NL+NL+"DEFENDER CHAIN MARK: <FOOTED|STRAINED|SLACK> -- <one clause naming the load-bearing link that decides the mark>."+NL+"CHALLENGER CHAIN MARK: <FOOTED|STRAINED|SLACK> -- <one clause naming the load-bearing link that decides the mark>."+NL+"These two lines come last, after OUT-OF-ROUND CONCESSIONS, the defender's first. One definition marks each side's own constructed chain, the defender's declared chain (D1 to the conclusion link) and the challenger's own alternative reading: FOOTED = every load-bearing link of the side's chain is footed on an exhibited L1-L3 layer; its reading stands as a built structure. STRAINED = the chain is built but one or more load-bearing links float: a link floats only when the block that states it exhibits fewer than two prior layers; the mark names the layers exhibited and the layer lacking; it stands only under charity. SLACK = the side advanced no coherent chain of its own: objections without a constructed reading, or a construction that never cohered. Each mark describes ONLY how well that side built its own chain. It is descriptive, not a verdict. It MUST NOT change DEFENSE STANDING, CHALLENGE STANDING, CONCEDED LINKS, CHALLENGER CONCEDED LINKS, the CLAUSE line, KEYSTONE or the top-line verdict. A FOOTED chain is fully compatible with its side losing the debate; a SLACK chain is fully compatible with its side winning it."
,'',
'If the transcript genuinely will not settle it, choose the tag the rulebook gives on the evidence that is there and say plainly in reasoning what is unresolved. A hung panel is a legitimate outcome of three honest judges; it is not your job to manufacture agreement.'].join('\n');
