if(S.rulebook==='draft'){const rep=(a,b)=>{const n=SYS.split(a).length-1;if(n!==1)throw new Error('FAIL-CLOSED: draft rulebook anchor found '+n+' times: '+a.slice(0,60)+RT);SYS=SYS.split(a).join(b);};
 rep('[L4]=Inference -- flag explicitly.','[L4]=Inference -- flag explicitly.'+NL+"SUPPLIED WORDS: A bracketed word or phrase inside the verse text is supplied by the translators. A bracket is a translators' margin when it contains a colon, '...', 'or,', 'Heb.' or 'Gr.'. An epistle subscription, a note on ancient copies, and a Psalm title are not supplied words. An [L2] answer shows the source has no word there. It breaks a link only when the link's load is the specific sense of the supplied word or phrase; the holder may answer by exhibiting that the source grammar carries that sense.");
 rep('HELD-1: none of the above.',"PARTIAL-3: the defender's keystone Dn was charged CONTESTED EXCLUSIVITY and graded EXCLUSIVITY UNMET, AND the challenger's keystone is MET, NOT CHARGED, or answered NON-EXCLUSIVE."+NL+'HELD-1: none of the above.');
 rep('Every other case gives UNDERDETERMINED.',"Every other case gives UNDERDETERMINED. BAR, applied first: a side's WINS is barred when its own keystone was charged CONTESTED EXCLUSIVITY and graded EXCLUSIVITY UNMET, or answered NON-EXCLUSIVE; a barred WINS gives UNDERDETERMINED.");
 rep('PARTIAL-1 | PARTIAL-2 | HELD-1>','PARTIAL-1 | PARTIAL-2 | PARTIAL-3 | HELD-1>');
 rep('WITHDRAWN | BROKEN | STANDS -- name','WITHDRAWN | BROKEN | STANDS | STANDS (EXCLUSIVITY UNMET) -- name');
 rep('STANDS otherwise.',"STANDS (EXCLUSIVITY UNMET) if it stands and was charged CONTESTED EXCLUSIVITY and graded EXCLUSIVITY UNMET; STANDS otherwise.");
 rep('Then SIX MORE mandatory lines','Then SEVEN MORE mandatory lines');
 rep('A side with any link graded BROKEN here cannot be SELF-SUPPORTED.','A side with any link graded BROKEN here cannot be SELF-SUPPORTED.'+NL+"CONTESTED EXCLUSIVITY. A declared link is EXCLUSIVE when its conclusion rules out a rival reading (only X; not Y). Either side may charge an exclusive link of the other in its premise list as LINK n: CONTESTED EXCLUSIVITY, carrying the verbatim quote of the exclusive claim and the rival reading's own exhibited footing: two of [L1] verse, [L2] word, [L3] cross-reference the charging side exhibits itself; a record label (#N, S-N) is not footing by itself. In its link round the holder answers EXCLUSIVE, exhibiting footing that excludes the rival reading (footing for its own reading alone does not), or NON-EXCLUSIVE, withdrawing only the exclusivity. An exclusion may be carried by a chain. It is met when the holder exhibits (a) text the rival reading must contradict, or (b) that the rival's exhibited footing does not reach the slot (a different referent, time or party), or (c) a prior-layer fact under which both readings cannot be true. No single verse naming the rival is required. Re-assertion is repeating the conclusion, or footing the rival reading also accommodates. A re-assertion, footing that supports both readings, or no answer grades EXCLUSIVITY UNMET. An unmet link STANDS; nothing breaks on L3 alone. A NON-EXCLUSIVE answer is not a withdrawal and never enters w. A CONTESTED EXCLUSIVITY charge is graded on the EXCLUSIVITY line only; it never enters L, c, CONCEDED LINKS, CHALLENGER CONCEDED LINKS or either standing."+NL+"EXCLUSIVITY: D<n> MET | UNMET | NON-EXCLUSIVE | NOT CHARGED; C<m> MET | UNMET | NON-EXCLUSIVE | NOT CHARGED -- this line comes directly after the COLLISION POINTS lines. D<n> is the defender's keystone; C<m> is the challenger's keystone, the LAST challenger link listed in [DR3], m their number. NOT CHARGED when no premise list charged that keystone CONTESTED EXCLUSIVITY.");
 rep('COLLISION POINTS, the citation check,','COLLISION POINTS, EXCLUSIVITY, the citation check,');
 rep('FORFEIT: if the challenger listed no premises against the defender',"LET STAND: if the challenger's list carries a LINK audit line for every declared defender link and marks none of them CHARGED, it is a reasoned let-stand, not a forfeit: L = 0, c = 0, CONCEDED LINKS is 0, DEFENSE STANDING cannot be COLLAPSED, and you add the line LINK ROUND LET STAND: CHALLENGER in place of the forfeit line. Otherwise "+'FORFEIT: if the challenger listed no premises against the defender');
 rep('FORFEIT: if the defender listed no premises against the challenger',"LET STAND: if the defender's list carries a LINK audit line for every challenger link and marks none of them CHARGED, it is a reasoned let-stand, not a forfeit: L = 0, c = 0, CHALLENGER CONCEDED LINKS is 0, CHALLENGE STANDING cannot be COLLAPSED, and you add the line LINK ROUND LET STAND: DEFENDER in place of the forfeit line. Otherwise "+'FORFEIT: if the defender listed no premises against the challenger');}
const JIDX={openai:0,gemini:1,grok:2,mimo:3,openrouter:4};const JIDX0={deepseek:0,openai:1,gemini:2,grok:3,mimo:4,openrouter:5};
const judges=RS.judges.map(j0=>{const j={...j0,max_tokens:Math.max(Number(j0.max_tokens)||0,8000)};const user='DEBATE TRANSCRIPT\n\n'+T;let body;
 if(j.fam==='gemini')body={systemInstruction:{parts:[{text:SYS}]},contents:[{role:'user',parts:[{text:user}]}],generationConfig:{maxOutputTokens:j.max_tokens+8192,temperature:0}};
 else{const m=[{role:'system',content:SYS},{role:'user',content:user}];
  // deepseek judge cap (BB-5700 step 5): its reasoning spent the whole 32,000 before answering (ODV1-25720; ODV1-25744 also returned empty content, cause not read); 65,536 passed at judge size (exec 25745).
  if(j.fam==='deepseek')body={model:j.api_model,max_tokens:Math.max(j.max_tokens,65536),temperature:0,messages:m};
  else if(j.fam==='grok')body={model:j.api_model,max_tokens:j.max_tokens,temperature:0,messages:m};
  else if(j.fam==='openai')body={model:j.api_model,max_completion_tokens:Math.max(j.max_tokens*2,8000),messages:m};
  // BB-8403 S3: chatgpt via OpenRouter (openai/) at reasoning effort medium; at max it spent the whole 32,000 in reasoning and returned no text (ODV1-29876 C1). Token budget as its openai branch: max(mt*2,8000).
  // BB-8403 S3: glm as a primary judge takes the reserve's glm body, effort medium (Reserve Build; BB-5693 rev 6).
  // BB-8510 S2: gemini via OpenRouter (google/), effort medium; max_tokens and temperature as its former generationConfig (KB-0042, KB-0077).
  else if(j.fam==='openrouter'&&/^google\//.test(j.api_model))body={model:j.api_model,max_tokens:j.max_tokens+8192,temperature:0,reasoning:{effort:'medium'},messages:m};
  else if(j.fam==='openrouter'&&/^openai\//.test(j.api_model))body={model:j.api_model,max_tokens:Math.max(j.max_tokens*2,8000),reasoning:{effort:'medium'},messages:m};
  else if(j.fam==='openrouter'&&j.seat==='glm')body={model:j.api_model,max_tokens:j.max_tokens,reasoning:{effort:'medium'},messages:m};
  else if(j.fam==='openrouter')body={model:j.api_model,max_tokens:j.max_tokens,reasoning:{effort:'max'},messages:m};
  // mimo judge (BB-5700 step 8a): thinking disabled. With thinking on, max_tokens 65,536 did not answer within the 900 s limit (exec 25738) and max_completion_tokens 32,000 took 645 s; disabled answered in 57 s (exec 25753).
  else if(j.fam==='mimo')body={model:j.api_model,max_tokens:Math.max(j.max_tokens,65536),messages:m,thinking:{type:'disabled'}};
  else body={model:j.api_model,max_tokens:j.max_tokens,messages:m};}
 return {seat:j.seat,fam:j.fam,jidx:(j.fam in JIDX)?JIDX[j.fam]:-1,jidx0:(j.fam in JIDX0)?JIDX0[j.fam]:-1,api_model:j.api_model,body};});
